import bpy, os
# Keep the noodle lift to the side so both of the chef's eyes read clearly.
for o in bpy.data.objects:
    if o.name.startswith('Hanging ribbon of ramen'):
        for i,p in enumerate(o.data.splines[0].bezier_points):
            p.co.x += [.55,.55,.48,.25,0][i]
    if o.name.startswith('Chef long bamboo chopsticks'):
        # Cylinder axis endpoints were .39...2.13; reshape around the same held end.
        from mathutils import Vector
        yy=-.66 if o.name=='Chef long bamboo chopsticks' else -.79
        a=Vector((.94,yy,3.67));b=Vector((2.13,yy+.12,3.88))
        o.location=(a+b)/2;o.dimensions.z=(b-a).length;o.rotation_euler=(b-a).to_track_quat('Z','Y').to_euler()
# Lower tessellation for smooth but efficient web delivery.
for c in bpy.data.curves:
    c.resolution_u=8;c.bevel_resolution=2
    if c.type=='FONT':c.resolution_u=5;c.bevel_resolution=1
sc=bpy.context.scene;sc.cycles.samples=64;sc.render.resolution_x=1500;sc.render.resolution_y=1500;sc.render.filepath=os.path.join(os.getcwd(),'output','01_ink_and_noodle.png')
bpy.ops.wm.save_as_mainfile(filepath=os.path.join(os.getcwd(),'scene_work.blend'))
bpy.ops.render.render(write_still=True)
result={'image':sc.render.filepath,'bytes':os.path.getsize(sc.render.filepath)}
